// Find SwingWindup parameter type
var swingWindupParam = System.Array.Find(controller.parameters, p => p.name == "SwingWindup");
UnityEngine.Debug.Log($"SwingWindup parameter type: {swingWindupParam.type}");

// Search all transitions for SwingWindup conditions
foreach (var layer in controller.layers)
{
    var sm = layer.stateMachine;
    CheckTransitions(sm, layer.name);
}

void CheckTransitions(UnityEditor.Animations.AnimatorStateMachine sm, string layerName)
{
    // Check AnyState transitions
    foreach (var t in sm.anyStateTransitions)
    {
        foreach (var cond in t.conditions)
        {
            if (cond.parameter == "SwingWindup")
            {
                UnityEngine.Debug.Log($"[AnyState→{t.destinationState?.name ?? "null"}] SwingWindup condition mode={cond.mode}");
            }
        }
    }

    // Check state transitions
    foreach (var state in sm.states)
    {
        foreach (var t in state.state.transitions)
        {
            foreach (var cond in t.conditions)
            {
                if (cond.parameter == "SwingWindup")
                {
                    UnityEngine.Debug.Log($"[{state.state.name}→{t.destinationState?.name ?? "null"}] SwingWindup condition mode={cond.mode}");
                }
            }
        }
    }

    // Recurse into sub-state machines
    foreach (var sub in sm.stateMachines)
    {
        CheckTransitions(sub.stateMachine, layerName + "/" + sub.stateMachine.name);
    }
}

var controllerPath = "Assets/Flynn/Animations/Flynn_AnimatorController.controller";
