var controllerPath = "Assets/Flynn/Animations/Flynn_AnimatorController.controller";
var controller = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(controllerPath);

int fixedCount = 0;
foreach (var layer in controller.layers)
{
    var sm = layer.stateMachine;
    foreach (var t in sm.anyStateTransitions)
    {
        // Find transitions that have SwingWindup IfNot condition (the invalid ones)
        bool hasBadCondition = false;
        foreach (var c in t.conditions)
        {
            if (c.parameter == "SwingWindup" && c.mode == UnityEditor.Animations.AnimatorConditionMode.IfNot)
            {
                hasBadCondition = true;
                break;
            }
        }

        if (hasBadCondition)
        {
            // Remove old conditions and rebuild with SwingCharging instead
            var newConditions = new System.Collections.Generic.List<UnityEditor.Animations.AnimatorCondition>();
            foreach (var c in t.conditions)
            {
                if (c.parameter == "SwingWindup" && c.mode == UnityEditor.Animations.AnimatorConditionMode.IfNot)
                {
                    // Replace with SwingCharging IfNot
                    newConditions.Add(new UnityEditor.Animations.AnimatorCondition
                    {
                        parameter = "SwingCharging",
                        mode = UnityEditor.Animations.AnimatorConditionMode.IfNot,
                        threshold = 0f
                    });
                    fixedCount++;
                }
                else
                {
                    newConditions.Add(c);
                }
            }

            t.conditions = newConditions.ToArray();
            UnityEngine.Debug.Log($"Fixed: AnyState→{t.destinationState?.name} replaced SwingWindup IfNot with SwingCharging IfNot");
        }
    }
}

UnityEditor.EditorUtility.SetDirty(controller);
UnityEditor.AssetDatabase.SaveAssets();
UnityEngine.Debug.Log($"Total conditions fixed: {fixedCount}");

