var controllerPath = "Assets/Flynn/Animations/Flynn_AnimatorController.controller";
var controller = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(controllerPath);

foreach (var layer in controller.layers)
{
    var sm = layer.stateMachine;
    foreach (var state in sm.states)
    {
        var s = state.state;
        if (s.name.StartsWith("SwingWindup") || s.name.StartsWith("Swing_") || s.name.StartsWith("SwingRelease"))
        {
            var clip = s.motion as UnityEngine.AnimationClip;
            string clipInfo = clip != null ? $"clip={clip.name} loop={clip.isLooping} len={clip.length:F2}s" : "motion=null";
            UnityEngine.Debug.Log($"State: {s.name} | speed={s.speed} | cycleOff={s.cycleOffsetParameter} | motionParam={s.speedParameter} | {clipInfo}");

            // Check transitions FROM this state
            foreach (var t in s.transitions)
            {
                var conds = new System.Collections.Generic.List<string>();
                foreach (var c in t.conditions) conds.Add($"{c.parameter} {c.mode} {c.threshold}");
                UnityEngine.Debug.Log($"  →{t.destinationState?.name ?? "exit"} [{string.Join(", ", conds)}] hasExitTime={t.hasExitTime} exitTime={t.exitTime} duration={t.duration}");
            }
        }
    }
}

