int changed = 0;
foreach (var layer in controller.layers)
{
    var sm = layer.stateMachine;
    foreach (var state in sm.states)
    {
        if (state.state.name.StartsWith("SwingWindup"))
        {
            var clip = state.state.motion as UnityEngine.AnimationClip;
            if (clip != null && clip.isLooping)
            {
                clip.isLooping = false;
                UnityEditor.EditorUtility.SetDirty(clip);
                changed++;
                UnityEngine.Debug.Log($"Set {clip.name} looping=false");
            }
        }
    }
}
UnityEditor.AssetDatabase.SaveAssets();
UnityEngine.Debug.Log($"Changed {changed} SwingWindup clips to non-looping");

