// Check the SwingWindup transitions - they need to have both Swing trigger AND SwingCharging=false
// so the windup stays at last frame while charging, then transitions on release
var controllerPath = "Assets/Flynn/Animations/Flynn_AnimatorController.controller";
var controller = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(controllerPath);

foreach (var layer in controller.layers)
{
    var sm = layer.stateMachine;
    foreach (var state in sm.states)
    {
        if (state.state.name.StartsWith("SwingWindup"))
        {
            foreach (var t in state.state.transitions)
            {
                var conds = new System.Collections.Generic.List<string>();
                foreach (var c in t.conditions) conds.Add($"{c.parameter} {c.mode}");
                UnityEngine.Debug.Log($"{state.state.name} → {t.destinationState?.name ?? "exit"} [{string.Join(", ", conds)}] hasExitTime={t.hasExitTime} exitTime={t.exitTime} canTransitionToSelf={t.canTransitionToSelf}");
            }
        }
    }
}

