    foreach (var t in layer.stateMachine.anyStateTransitions)
    {
        if (t.destinationState?.name.StartsWith("Swing_") == true)
        {
            // Extract direction suffix: "Swing_DownLeft" → "DownLeft"
            string suffix = t.destinationState.name.Substring("Swing_".Length);
            if (dirMap.TryGetValue(suffix, out int dirVal))
            {
                var conditions = new System.Collections.Generic.List<UnityEditor.Animations.AnimatorCondition>(t.conditions);
                conditions.Add(new UnityEditor.Animations.AnimatorCondition
                {
                    parameter = "FacingDir",
                    mode = UnityEditor.Animations.AnimatorConditionMode.Equals,
                    threshold = dirVal
                });
                t.conditions = conditions.ToArray();
                fixedTransitions++;
                UnityEngine.Debug.Log($"Added FacingDir={dirVal} to AnyState→{t.destinationState.name}");
            }
        }
    }
}

// 2. Change SwingWindup→SwingRelease from "Swing If" to "SwingCharging IfNot"
foreach (var layer in controller.layers)
{
    foreach (var state in layer.stateMachine.states)
    {
        if (state.state.name.StartsWith("SwingWindup"))
        {
            foreach (var t in state.state.transitions)
            {
                if (t.destinationState?.name.StartsWith("SwingRelease") == true)
                {
                    var newConds = new System.Collections.Generic.List<UnityEditor.Animations.AnimatorCondition>();
                    foreach (var c in t.conditions)
                    {
                        if (c.parameter == "Swing" && c.mode == UnityEditor.Animations.AnimatorConditionMode.If)
                        {
                            // Replace Swing If with SwingCharging IfNot
                            newConds.Add(new UnityEditor.Animations.AnimatorCondition
                            {
                                parameter = "SwingCharging",
                                mode = UnityEditor.Animations.AnimatorConditionMode.IfNot,
                                threshold = 0f
                            });
                            fixedTransitions++;
                            UnityEngine.Debug.Log($"Changed {state.state.name}→{t.destinationState.name}: Swing If → SwingCharging IfNot");
                        }
                        else
                        {
                            newConds.Add(c);
                        }
                    }
                    t.conditions = newConds.ToArray();
                }
            }
        }
    }
}

UnityEditor.EditorUtility.SetDirty(controller);
UnityEditor.AssetDatabase.SaveAssets();
UnityEngine.Debug.Log($"Total transitions fixed: {fixedTransitions}");

