    private void OnToolSwingStarted(ToolSwingStarted evt)
    {
        Debug.Log($"[FeedbackManager] Swing VFX \u2014 tool {evt.ToolType}, aim point {evt.AimPoint}");
    }

    private void OnToolHitTarget(ToolHitTarget evt)
    {
        Debug.Log($"[FeedbackManager] Impact VFX at {evt.Hit.HitPoint} \u2014 tool {evt.Hit.ToolType}, damage {evt.Hit.Damage}");
    }

    private void OnItemPickedUp(ItemPickedUp evt)
    {
        Debug.Log($"[FeedbackManager] Pickup sparkle \u2014 item {evt.Item?.name ?? "unknown"}, count {evt.Count}");
    }

    private void OnRopeGrappleStarted(RopeGrappleStarted evt)
    {
        Debug.Log($"[FeedbackManager] Grapple launch effect \u2014 anchor {evt.Anchor?.name ?? "unknown"}");
    }

    private void OnBatteryLow(BatteryLow evt)
    {
        Debug.Log($"[FeedbackManager] Warning pulse \u2014 battery {evt.Current} ({evt.Percent:P0})");
    }

    private void OnBatteryEmpty(BatteryEmpty evt)
    {
        Debug.Log("[FeedbackManager] Screen flash \u2014 battery empty");
    }
}

using UnityEngine;

/// <summary>
/// Immutable payload for a single player "hit" event (a swing/strike landing). Carried by
/// <see cref="PlayerHitChannel"/> from the player to the <see cref="ResourceManager"/>, which
/// re-broadcasts it to registered resources. Deliberately generic: it describes WHAT happened,
/// not WHO should react — the resource layer decides that later.
/// </summary>
public readonly struct PlayerHitInfo
{
    /// <summary>World-space point the hit landed at.</summary>
    public readonly Vector3 Point;

    /// <summary>The struck GameObject, if the player resolved one. May be null (whiffed swing).</summary>
    public readonly GameObject Target;

