using System.Collections;
using UnityEngine;

/// <summary>
/// Simple camera shake using a local offset on the Main Camera's transform.
/// Works with or without Cinemachine. Uses unscaled time so it still plays
/// during hit-stop (when Time.timeScale is briefly frozen).
/// </summary>
public class CameraShake : MonoBehaviour
{
    [SerializeField] private float _defaultIntensity = 0.15f;
    [SerializeField] private float _defaultDuration = 0.2f;
    [SerializeField] private float _frequency = 25f;

    private static CameraShake _instance;
    public static CameraShake Instance => _instance;

    private Vector3 _originalLocalPos;
    private Coroutine _routine;

    private void Awake()
    {
        _instance = this;
        _originalLocalPos = transform.localPosition;
    }

    /// <summary>Shake with default intensity.</summary>
    public void Shake() => Shake(_defaultIntensity, _defaultDuration);

    /// <summary>Shake with custom intensity and duration.</summary>
    public void Shake(float intensity, float duration)
    {
        if (_routine != null) StopCoroutine(_routine);
        _routine = StartCoroutine(ShakeRoutine(intensity, duration));
    }

    private IEnumerator ShakeRoutine(float intensity, float duration)
    {
        float t = 0f;
        while (t < duration)
        {
            t += Time.unscaledDeltaTime;
            float decay = 1f - (t / duration);
            float x = Mathf.PerlinNoise(t * _frequency, 0f) * 2f - 1f;
            float y = Mathf.PerlinNoise(0f, t * _frequency) * 2f - 1f;
            transform.localPosition = _originalLocalPos + new Vector3(x, y, 0f) * intensity * decay;
            yield return null;
        }
        transform.localPosition = _originalLocalPos;
        _routine = null;
    }
}

