using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Hold to charge power via
/// <see cref="PowerBuildupManager"/>; release to swing with scaled damage and
/// battery cost. Tap for a light swing. The swing faces the mouse aim point.
/// Routes damage through the ResourceManager observer pattern.
/// Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [SerializeField] private PowerBuildupSettings _buildupSettings;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    [Tooltip("Hold longer than this (seconds) to enter windup. Taps skip straight to swing.")]
    [SerializeField] private float _quickSwingThreshold = 0.12f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _movement;
    private PowerBuildupManager _buildup;
    private float _cooldown;
    private float _windupStartTime;

    public bool IsCharging => _buildup != null && _buildup.IsCharging && _buildup.CurrentType == ActionType.Swing;
    public float ChargeNormalized => _buildup != null ? _buildup.ChargeNormalized : 0f;

    /// <summary>True while the swing animation is still playing (movement blocked).</summary>
    public bool IsSwinging { get; private set; }

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _movement   = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        // Block movement while swinging
        if (IsSwinging)
        {
            if (_movement != null) _movement.CanMove = false;

            // Check if the swing animation has finished
            var driver = _animDriver as FlynnAnimationDriver;
            if (driver != null && !driver.IsAttacking)
                IsSwinging = false;
        }

        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            if (IsCharging) _buildup.CancelCharge();
            if (_animDriver is FlynnAnimationDriver drv)
                drv.CancelSwingWindup();
            return;
        }

        if (_buildup == null) _buildup = PowerBuildupManager.Instance;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            if (_buildup != null) _buildup.BeginCharge(ActionType.Swing);
            _windupStartTime = Time.time;
            // Face the mouse aim point and start the windup animation
            if (_animDriver != null)
            {
                _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
                _animDriver.BeginSwingWindup();
            }
        }
        else if (IsCharging && Input.GetMouseButtonUp(0))
        {
            bool quickSwing = Time.time - _windupStartTime < _quickSwingThreshold;
            DoSwing(quickSwing);
        }
    }

    private void DoSwing(bool quickSwing = false)
    {
        if (_buildup == null) return;

        ChargeResult result = _buildup.ReleaseCharge();

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = result.AnimSpeed > 0f ? result.AnimSpeed : 1f;
        if (_animDriver != null)
        {
            if (quickSwing)
            {
                _animDriver.CancelSwingWindup();
                _animDriver.TriggerSwing();
            }
            else
            {
                _animDriver.ReleaseSwing(animIndex, speed);
            }
        }

        IsSwinging = true;
        if (_movement != null) _movement.CanMove = false;

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        int damage = result.Damage > 0 ? result.Damage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Scene-level manager for VFX feedback. Subscribes to GameEventBus events
/// and drives HitImpactFX, CameraShake, and HitStop for juicy combat feel.
/// One per scene on the MANAGERS GameObject. NOT a singleton.
/// </summary>
public class FeedbackManager : MonoBehaviour
{
    // ── Resource-type colors ────────────────────────────────────────────────

    private static readonly Color StoneColor    = new Color(0.75f, 0.72f, 0.68f);
    private static readonly Color WoodColor     = new Color(0.65f, 0.45f, 0.2f);
    private static readonly Color TechColor     = new Color(0.3f, 0.85f, 0.95f);
    private static readonly Color DefaultColor  = new Color(1f, 0.85f, 0.4f);

    // ── Unity messages ──────────────────────────────────────────────────────

    private void OnEnable()
    {
        GameEventBus.Instance.Subscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Subscribe<ResourceDepleted>(OnResourceDepleted);
        GameEventBus.Instance.Subscribe<ToolSwingStarted>(OnToolSwingStarted);
        GameEventBus.Instance.Subscribe<ToolHitTarget>(OnToolHitTarget);
        GameEventBus.Instance.Subscribe<ItemPickedUp>(OnItemPickedUp);
        GameEventBus.Instance.Subscribe<RopeGrappleStarted>(OnRopeGrappleStarted);
        GameEventBus.Instance.Subscribe<BatteryLow>(OnBatteryLow);
        GameEventBus.Instance.Subscribe<BatteryEmpty>(OnBatteryEmpty);
    }

    private void OnDisable()
    {
        if (GameEventBus.Instance == null) return;
        GameEventBus.Instance.Unsubscribe<ResourceDamaged>(OnResourceDamaged);
        GameEventBus.Instance.Unsubscribe<ResourceDepleted>(OnResourceDepleted);
        GameEventBus.Instance.Unsubscribe<ToolSwingStarted>(OnToolSwingStarted);
        GameEventBus.Instance.Unsubscribe<ToolHitTarget>(OnToolHitTarget);
        GameEventBus.Instance.Unsubscribe<ItemPickedUp>(OnItemPickedUp);
        GameEventBus.Instance.Unsubscribe<RopeGrappleStarted>(OnRopeGrappleStarted);
        GameEventBus.Instance.Unsubscribe<BatteryLow>(OnBatteryLow);
        GameEventBus.Instance.Unsubscribe<BatteryEmpty>(OnBatteryEmpty);
    }

    // ── Event handlers ──────────────────────────────────────────────────────

    private void OnResourceDamaged(ResourceDamaged evt)
    {
        var fx = HitImpactFX.Instance;
        if (fx == null) return;

        Color color = ResourceColor(evt.Node);
        Vector3 dir = evt.Node != null ? evt.Position - transform.position : Vector3.forward;
        float strength = Mathf.Clamp01(evt.Damage / 3f);

        fx.PlayHit(evt.Position, dir, evt.Damage, color);
        PlayCameraShake(0.08f + 0.12f * strength, 0.15f);
        PlayHitStop(strength);
    }

    private void OnResourceDepleted(ResourceDepleted evt)
    {
        var fx = HitImpactFX.Instance;
        if (fx == null) return;

        Color color = ResourceColor(evt.Node);
        Vector3 dir = evt.Node != null ? evt.Position - transform.position : Vector3.forward;

        // Bigger burst for depletion
        fx.PlayHit(evt.Position, dir, 0, color);
        PlayCameraShake(0.25f, 0.3f);
        PlayHitStop(1f);
    }

    private void OnToolSwingStarted(ToolSwingStarted evt)
    {
        // Air whoosh for swings that don't hit a target
        var fx = HitImpactFX.Instance;
        if (fx != null)
            fx.PlayAirWhoosh(evt.AimPoint, evt.AimPoint - transform.position);
    }

    private void OnToolHitTarget(ToolHitTarget evt)
    {
        var fx = HitImpactFX.Instance;
        if (fx == null) return;

        var hit = evt.Hit;
        float strength = Mathf.Clamp01(hit.Damage / 3f);

        // Determine if this hit a ResourceNode or a generic surface
        var node = hit.Source != null ? hit.Source.GetComponentInParent<ResourceNode>() : null;
        if (node != null)
        {
            // ResourceNode hits are handled by OnResourceDamaged above
            return;
        }

        // Generic surface hit — sparks / dust
        fx.PlaySurfaceHit(hit.HitPoint, hit.HitDirection);
        PlayCameraShake(0.05f, 0.1f);
        PlayHitStop(strength * 0.5f);
    }

    private void OnItemPickedUp(ItemPickedUp evt)
    {
        // Future: pickup sparkle
    }

    private void OnRopeGrappleStarted(RopeGrappleStarted evt)
    {
        // Future: grapple launch effect
    }

    private void OnBatteryLow(BatteryLow evt)
    {
        // Future: warning pulse
    }

    private void OnBatteryEmpty(BatteryEmpty evt)
    {
        // Future: screen flash
    }

    // ── Helpers ─────────────────────────────────────────────────────────────

    private static Color ResourceColor(ResourceNode node)
    {
        if (node == null) return DefaultColor;
        return node.ResourceType switch
        {
            ResourceType.Stone    => StoneColor,
            ResourceType.Wood     => WoodColor,
            ResourceType.TechTrash => TechColor,
            _ => DefaultColor
        };
    }

    private static void PlayCameraShake(float intensity, float duration)
    {
        var shake = CameraShake.Instance;
        if (shake != null) shake.Shake(intensity, duration);
    }

    private static void PlayHitStop(float strength)
    {
        var stop = HitStop.Instance;
        if (stop != null) stop.Play(strength);
    }
}

