using System.Collections;
using UnityEngine;

/// <summary>
/// Procedural hit-impact VFX: particle burst, expanding flash ring, and floating
/// damage number. All generated at runtime — no prefab assets required.
/// Attach one to the MANAGERS object (or any persistent GameObject).
/// </summary>
public class HitImpactFX : MonoBehaviour
{
    [Header("Impact Particles")]
    [SerializeField] private int _particleCount = 12;
    [SerializeField] private float _particleSpeed = 4f;
    [SerializeField] private float _particleLife = 0.5f;
    [SerializeField] private float _particleSize = 0.12f;

    [Header("Flash Ring")]
    [SerializeField] private float _flashStartScale = 0.2f;
    [SerializeField] private float _flashEndScale = 1.2f;
    [SerializeField] private float _flashDuration = 0.15f;

    [Header("Damage Number")]
    [SerializeField] private float _numberDuration = 0.8f;
    [SerializeField] private float _numberRiseSpeed = 1.5f;

    [Header("Air Whoosh")]
    [SerializeField] private int _whooshParticleCount = 6;
    [SerializeField] private float _whooshSpeed = 2.5f;
    [SerializeField] private float _whooshLife = 0.3f;

    private static HitImpactFX _instance;
    public static HitImpactFX Instance => _instance;

    private void Awake() => _instance = this;

    // ── Public API ─────────────────────────────────────────────────────────

    /// <summary>Full impact: particles + flash + damage number + optional camera shake.</summary>
    public void PlayHit(Vector3 position, Vector3 direction, int damage, Color color)
    {
        SpawnParticleBurst(position, direction, _particleCount, _particleSpeed, _particleLife, color);
        StartCoroutine(FlashRingRoutine(position, color));
        if (damage > 0) SpawnDamageNumber(position, damage, color);
    }

    /// <summary>Light impact for non-resource surfaces (sparks / dust).</summary>
    public void PlaySurfaceHit(Vector3 position, Vector3 direction)
    {
        var dustColor = new Color(0.7f, 0.65f, 0.55f);
        SpawnParticleBurst(position, direction, _particleCount / 2, _particleSpeed * 0.7f, _particleLife, dustColor);
        StartCoroutine(FlashRingRoutine(position, dustColor));
    }

    /// <summary>Air whoosh on a swing that hits nothing.</summary>
    public void PlayAirWhoosh(Vector3 position, Vector3 direction)
    {
        var whooshColor = new Color(1f, 0.95f, 0.8f, 0.4f);
        SpawnParticleBurst(position, direction, _whooshParticleCount, _whooshSpeed, _whooshLife, whooshColor);
    }

    // ── Particle burst ─────────────────────────────────────────────────────

    private void SpawnParticleBurst(Vector3 pos, Vector3 dir, int count, float speed, float life, Color color)
    {
        for (int i = 0; i < count; i++)
        {
            var go = CreateQuad($"_hitParticle_{i}");
            go.transform.position = pos;
            go.transform.localScale = Vector3.one * _particleSize;

            var sr = go.GetComponent<SpriteRenderer>();
            sr.color = color;
            sr.sortingOrder = 100;

            StartCoroutine(ParticleRoutine(go, pos, dir, speed, life));
        }
    }

    private IEnumerator ParticleRoutine(GameObject go, Vector3 origin, Vector3 dir, float speed, float life)
    {
        float t = 0f;
        // Spread particles in a cone around the hit direction
        Vector3 spread = Random.onUnitSphere * 0.5f;
        Vector3 vel = (dir.normalized + spread).normalized * speed * Random.Range(0.6f, 1.2f);
        vel.y += Random.Range(1f, 3f); // upward bias

        var sr = go.GetComponent<SpriteRenderer>();
        while (t < life)
        {
            t += Time.unscaledDeltaTime;
            float p = t / life;
            go.transform.position += vel * Time.unscaledDeltaTime;
            vel.y -= 6f * Time.unscaledDeltaTime; // gravity
            vel *= 1f - 2f * Time.unscaledDeltaTime; // drag

            var c = sr.color;
            c.a = 1f - p;
            sr.color = c;

            // Shrink towards end
            float scale = _particleSize * (1f - p * 0.5f);
            go.transform.localScale = Vector3.one * scale;

            yield return null;
        }
        Destroy(go);
    }

    // ── Flash ring ──────────────────────────────────────────────────────────

    private IEnumerator FlashRingRoutine(Vector3 pos, Color color)
    {
        var go = CreateQuad("_hitFlash");
        go.transform.position = pos + Vector3.up * 0.05f;
        go.transform.localScale = Vector3.one * _flashStartScale;

        var sr = go.GetComponent<SpriteRenderer>();
        sr.color = new Color(1f, 1f, 1f, 0.9f); // white flash
        sr.sortingOrder = 99;

        float t = 0f;
        while (t < _flashDuration)
        {
            t += Time.unscaledDeltaTime;
            float p = t / _flashDuration;
            float ease = 1f - (1f - p) * (1f - p); // ease out
            float scale = Mathf.Lerp(_flashStartScale, _flashEndScale, ease);
            go.transform.localScale = Vector3.one * scale;

            var c = sr.color;
            c.a = 0.9f * (1f - p);
            sr.color = c;

            yield return null;
        }
        Destroy(go);
    }

    // ── Damage number ──────────────────────────────────────────────────────

    private void SpawnDamageNumber(Vector3 pos, int damage, Color color)
    {
        var go = new GameObject("_dmgNum");
        go.transform.position = pos + Vector3.up * 0.8f;

        var canvas = FindObjectOfType<Canvas>();
        if (canvas == null)
        {
            // Fallback: world-space text using 3D TextMesh
            var tm = go.AddComponent<TextMesh>();
            tm.text = damage.ToString();
            tm.fontSize = 24;
            tm.color = color;
            tm.alignment = TextAlignment.Center;
            tm.anchor = TextAnchor.MiddleCenter;
            tm.characterSize = 0.06f;
            var rend = go.GetComponent<MeshRenderer>();
            rend.sortingOrder = 200;
            StartCoroutine(DamageNumberRoutine(go));
            return;
        }

        // Screen-space version using UI text
        var rt = go.AddComponent<RectTransform>();
        go.transform.SetParent(canvas.transform, false);
        var txt = go.AddComponent<UnityEngine.UI.Text>();
        txt.text = damage.ToString();
        txt.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        txt.fontSize = 28;
        txt.fontStyle = FontStyle.Bold;
        txt.color = color;
        txt.alignment = TextAnchor.MiddleCenter;
        txt.horizontalOverflow = HorizontalWrapMode.Overflow;
        txt.verticalOverflow = VerticalWrapMode.Overflow;
        txt.raycastTarget = false;

        // Position at world point on canvas
        var cam = Camera.main;
        if (cam != null)
        {
            var screenPos = cam.WorldToScreenPoint(pos + Vector3.up * 1f);
            rt.position = screenPos;
        }

        StartCoroutine(DamageNumberUIRoutine(go, rt, cam, pos));
    }

    private IEnumerator DamageNumberRoutine(GameObject go)
    {
        float t = 0f;
        var tm = go.GetComponent<TextMesh>();
        while (t < _numberDuration)
        {
            t += Time.unscaledDeltaTime;
            float p = t / _numberDuration;
            go.transform.position += Vector3.up * _numberRiseSpeed * Time.unscaledDeltaTime;

            var c = tm.color;
            c.a = 1f - p;
            tm.color = c;

            // Scale punch: grow then shrink
            float scalePunch = 1f + 0.3f * Mathf.Sin(p * Mathf.PI);
            go.transform.localScale = Vector3.one * scalePunch;

            yield return null;
        }
        Destroy(go);
    }

    private IEnumerator DamageNumberUIRoutine(GameObject go, RectTransform rt, Camera cam, Vector3 worldPos)
    {
        float t = 0f;
        var txt = go.GetComponent<UnityEngine.UI.Text>();
        var basePos = rt.position;
        while (t < _numberDuration)
        {
            t += Time.unscaledDeltaTime;
            float p = t / _numberDuration;

            basePos.y += _numberRiseSpeed * Time.unscaledDeltaTime * 80f;
            rt.position = basePos;

            var c = txt.color;
            c.a = 1f - p;
            txt.color = c;

            float scalePunch = 1f + 0.3f * Mathf.Sin(p * Mathf.PI);
            rt.localScale = Vector3.one * scalePunch;

            yield return null;
        }
        Destroy(go);
    }

    // ── Helpers ─────────────────────────────────────────────────────────────

    private static GameObject CreateQuad(string name)
    {
        var go = new GameObject(name);
        var sr = go.AddComponent<SpriteRenderer>();
        sr.sprite = CreateWhiteSprite();
        sr.material = new Material(Shader.Find("Sprites/Default"));
        return go;
    }

    private static Sprite _whiteSprite;
    private static Sprite CreateWhiteSprite()
    {
        if (_whiteSprite != null) return _whiteSprite;
        var tex = new Texture2D(1, 1);
        tex.SetPixel(0, 0, Color.white);
        tex.Apply();
        _whiteSprite = Sprite.Create(tex, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f), 1f);
        return _whiteSprite;
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// Positional recoil on a <see cref="ResourceNode"/> when it's hit — a quick decaying nudge so the
/// node visibly rocks from the blow. Amplitude scales with the damage dealt (heavy swings rock it
/// harder). Nudges the node root's position only: the sprite's rotation is owned by
/// <see cref="Billboard"/>, so a positional shake reads cleanly without fighting it.
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceShake : MonoBehaviour
{
    [Tooltip("Transform to nudge. Defaults to this node's transform.")]
    [SerializeField] private Transform _shakeRoot;
    [SerializeField] private float _duration = 0.18f;
    [SerializeField] private float _amplitude = 0.09f;
    [Tooltip("Damage that produces a full-strength shake; less damage shakes proportionally less.")]
    [SerializeField] private float _damageForFullShake = 3f;

    private ResourceNode _node;
    private Coroutine _routine;
    private Vector3 _basePos;
    private int _lastHealth;

    private void Awake()
    {
        _node = GetComponent<ResourceNode>();
        if (_shakeRoot == null) _shakeRoot = transform;
        _basePos = _shakeRoot.localPosition;
    }

    private void Start() => _lastHealth = _node.CurrentHealth;

    private void OnEnable()  { _node.OnDamaged += HandleDamaged; }
    private void OnDisable()
    {
        if (_node != null) _node.OnDamaged -= HandleDamaged;
        if (_shakeRoot != null) _shakeRoot.localPosition = _basePos;
    }

    private void HandleDamaged(int remaining)
    {
        int dmg = Mathf.Max(1, _lastHealth - remaining);
        _lastHealth = remaining;
        float strength = 0.4f + 0.6f * Mathf.Clamp01(dmg / Mathf.Max(1f, _damageForFullShake));

        if (_routine != null) StopCoroutine(_routine);
        _routine = StartCoroutine(ShakeRoutine(strength));
    }

    private IEnumerator ShakeRoutine(float strength)
    {
        Vector2 r = Random.insideUnitCircle.normalized;
        Vector3 dir = new Vector3(r.x, 0f, r.y);
        float t = 0f;
        while (t < _duration)
        {
            t += Time.deltaTime;
            float decay = 1f - (t / _duration);
            float wobble = Mathf.Sin(t * 55f) * decay * strength;
            _shakeRoot.localPosition = _basePos + dir * (_amplitude * wobble);
            yield return null;
        }
        _shakeRoot.localPosition = _basePos;
        _routine = null;
    }
}

