using UnityEngine;
using Flynn.Events;

/// <summary>
/// Projectile spawned by WrenchThrowController. Flies outbound to a target point,
/// hovers (returnDelay), then homes back to the thrower like a boomerang and is caught.
/// Spins a child visual for the boomerang look. On impact with a ResourceNode,
/// applies throw damage through the effectiveness system.
/// </summary>
public class ThrownWrench : MonoBehaviour
{
    private enum Phase { Outbound, Hover, Returning }

    private WrenchThrowController _owner;
    private WrenchConfig _config;
    private Vector3 _target;
    private Phase _phase;
    private float _hoverTimer;
    private Transform _spin;
    private Camera _cam;
    private float _roll;
    private bool _hasHitTarget;

    public void Launch(WrenchThrowController owner, Vector3 target, WrenchConfig config)
    {
        _owner   = owner;
        _target  = target;
        _config  = config;
        _phase   = Phase.Outbound;
        _spin    = transform.childCount > 0 ? transform.GetChild(0) : transform;
    }

    private void Update()
    {
        if (_config == null) return;

        switch (_phase)
        {
            case Phase.Outbound:
                MoveToward(_target, _config.throwSpeed);
                if (Reached(_target, 0.1f))
                {
                    _phase = Phase.Hover;
                    _hoverTimer = _config.returnDelay;
                }
                break;

            case Phase.Hover:
                _hoverTimer -= Time.deltaTime;
                if (_hoverTimer <= 0f) _phase = Phase.Returning;
                break;

            case Phase.Returning:
                Vector3 catchPoint = _owner != null ? _owner.CatchPoint : transform.position;
                MoveToward(catchPoint, _config.returnSpeed);
                if (Reached(catchPoint, _config.catchRadius))
                {
                    if (_owner != null) _owner.OnCaught();
                    Destroy(gameObject);
                }
                break;
        }
    }

    /// <summary>
    /// Detect collision with ResourceNodes during the outbound phase.
    /// Uses the effectiveness system to determine damage.
    /// </summary>
    private void OnCollisionEnter(Collision collision)
    {
        if (_phase != Phase.Outbound || _hasHitTarget) return;

        ResourceNode node = collision.gameObject.GetComponentInParent<ResourceNode>();
        if (node == null) return;

        _hasHitTarget = true;

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;

        int damage = _config != null ? _config.heavySwingDamage : 2;
        Vector3 hitDir = (collision.transform.position - transform.position).normalized;

        var hit = new ToolHitContext(
            source: gameObject,
            toolType: tool,
            action: ToolActionType.Throw,
            damage: damage,
            hitPoint: collision.contacts.Length > 0 ? collision.contacts[0].point : transform.position,
            hitDirection: hitDir,
            charge: 1f
        );

        node.TryApplyToolHit(hit);

        // Immediately start returning after impact
        _phase = Phase.Returning;
    }

    // Billboard the visual to the camera (like the player sprite) and spin it in the
    // screen plane so the boomerang reads as rotating regardless of view angle.
    private void LateUpdate()
    {
        if (_config == null || _spin == null) return;
        if (_cam == null) _cam = Camera.main;
        if (_cam == null) return;

        _roll += _config.spinSpeed * Time.deltaTime;
        _spin.rotation = _cam.transform.rotation * Quaternion.Euler(0f, 0f, _roll);
    }

    private void MoveToward(Vector3 p, float speed)
        => transform.position = Vector3.MoveTowards(transform.position, p, speed * Time.deltaTime);

    private bool Reached(Vector3 p, float radius)
        => (transform.position - p).sqrMagnitude <= radius * radius;
}

using UnityEngine;

/// <summary>
/// Describes a single inventory item. Assign via Inspector; instances live in
/// Assets/Flynn/Configs/Items/. The attackAnimIndex maps to the four attack
/// clips: 1 = pick, 2 = axe, 3 = hammer, 4 = wrench.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Item Definition", fileName = "ItemDefinition")]
public class ItemDefinition : ScriptableObject
{
    [Header("Identity")]
    public string itemId;
    public string displayName;
    public Sprite icon;

    [Header("Tool")]
    public ItemType itemType;

    [Tooltip("Animator AttackIndex (1-4) triggered when this tool swings. 0 = no attack.")]
    [Range(0, 4)]
    public int attackAnimIndex;

    [Header("Stacking")]
    [Tooltip("Maximum count of this item in one inventory slot. Tools (the wrench) should be 1.")]
    [Min(1)] public int maxStack = 3;

    [Header("World pickup")]
    [Tooltip("Prefab spawned to represent this item lying in / dropped into the world (carries a WorldItem). " +
             "Used by resource drops, the drop key, and drag-to-drop.")]
    public GameObject worldPrefab;

    [Tooltip("If true, world drops of this item fly to the player automatically once there's room. " +
             "If false (e.g. the wrench) the player must aim at it and press the pickup key.")]
    public bool autoCollect = true;

    [Header("Currency")]
    [Tooltip("If true this item is a currency: collecting it adds to currencyTarget instead of taking an inventory slot.")]
    public bool isCurrency = false;

    [Tooltip("Currency counter incremented when this item is collected. Only used when isCurrency is true.")]
    public IntVariable currencyTarget;

    /// <summary>True when this item should magnet to the player on drop (resources, currency).</summary>
    public bool AutoCollects => autoCollect || isCurrency;
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

