var ingameSprite = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Sprite>("Assets/Flynn/Sprites/Environment/wrench_ingame.png");

// Add a child visual with the wrench sprite
var visual = new UnityEngine.GameObject("Visual");
visual.transform.SetParent(prefab.transform, false);
var sr = visual.AddComponent<SpriteRenderer>();
sr.sprite = ingameSprite;
sr.sortingOrder = 50;
visual.transform.localScale = UnityEngine.Vector3.one * 0.5f; // smaller when thrown

