    // Change to ScaleWithScreenSize for 1920x1080
    UnityEditor.Undo.RecordObject(panelSettings, "Set Panel ScaleWithScreenSize");
    panelSettings.scaleMode = UnityEngine.UIElements.PanelScaleMode.ScaleWithScreenSize;
    panelSettings.referenceResolution = new UnityEngine.Vector2Int(1920, 1080);
    UnityEditor.EditorUtility.SetDirty(panelSettings);
    UnityEngine.Debug.Log($"Set scaleMode=ScaleWithScreenSize refRes=1920x1080");
}

